<?php declare(strict_types=1);
namespace Kulturhus\Native\Web\Communication;
use Kulturhus\Native\Web\{Html,Workspace};
use Kulturhus\Native\Communication\EditorialCatalogue;
use Kulturhus\Native\Language\{Catalog,EditorialHubMessages as Messages};
final class EditorialLibrary extends Workspace
{
    public function render(string $module,array $input):string
    {
        $messages=(new Catalog($this->db,$this->access))->messages();$t=static fn(string$s,array$v=[]):string=>Html::e(Messages::text($s,$messages,$v));$route=['view'=>$module,'section'=>'contents'];$url=static fn(array$q):string=>'/?'.http_build_query($route+$q);$h='<section class="editorial-library" data-editorial-library><h2>'.$t('Inhalte planen').'</h2><p>'.$t('Gespeicherte Inhalte und geplante Ausgaben gemeinsam bearbeiten.').'</p>';
        try{$page=EditorialCatalogue::page($this->db,$this->access,$input);}catch(\DomainException $error){http_response_code(in_array($error->getCode(),[403,409],true)?$error->getCode():422);$labels=[];foreach(['hub_query'=>'Titel oder Stichwort','hub_type'=>'Inhaltsart','hub_page'=>'Seite']as$key=>$label)if(array_key_exists($key,$input))$labels[Messages::text($label,$messages)]=$input[$key];return$h.'<p role="alert">'.$t($error->getMessage()).'</p><details open><summary>'.$t('Ursprüngliche Suchangaben').'</summary><pre>'.Html::e(json_encode($labels,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE)).'</pre></details><a class="btn btn-outline theme-secondary" data-nav href="'.Html::e($url([])).'">'.$t('Inhalte zurücksetzen').'</a></section>';}
        $types=['all'=>'Alle Inhalte'];foreach(['social'=>'Social-Beiträge','newsletter'=>'Newsletter']as$key=>$label)if(in_array($key,$page['modules'],true))$types[$key]=$label;
        $h.='<form method="get" class="editorial-library-search">'.Html::hidden('view',$module).Html::hidden('section','contents').Html::input('hub_query',Messages::text('Titel oder Stichwort',$messages),$page['query']).Html::select('hub_type',Messages::text('Inhaltsart',$messages),array_map(static fn($s)=>Messages::text($s,$messages),$types),$page['type']).'<button class="btn btn-outline theme-secondary">'.$t('Suchen').'</button></form><div class="editorial-library-grid">';
        foreach($page['rows']as$row){$kind=['newsletter'=>'Newsletter','post'=>'Beitrag','reel'=>'Reel','story'=>'Story','carousel'=>'Karussell','video'=>'Video','event'=>'Veranstaltung'][$row['kind']]??'Beitrag';$state=['draft'=>'Entwurf','review'=>'In Prüfung','approved'=>'Freigegeben','scheduled'=>'Geplant','local_ready'=>'Lokal vorbereitet','ambiguous'=>'Ergebnis prüfen'][$row['status']]??'Status prüfen';$h.='<article class="panel editorial-content-card" data-editorial-item="'.Html::e($row['id']).'" data-editorial-module="'.$row['module'].'"><p class="editorial-card-labels"><span class="social-plan-kind kind-'.Html::e($row['kind']).'">'.$t($kind).'</span><span>'.$t($state).'</span></p><h3>'.Html::e(is_string($row['title'])?$row['title']:Messages::text('Noch kein Titel gespeichert',$messages)).'</h3><a class="btn btn-outline theme-secondary" data-nav href="'.Html::e('/?'.http_build_query(['view'=>$row['module'],'section'=>'compose','item'=>$row['id']]).($row['kind']==='story'?'#social-image-editor':'')).'">'.$t($row['module']==='newsletter'?'Ausgabe öffnen':'Inhalt öffnen').'</a></article>';}
        $h.='</div>';if(!$page['rows'])$h.='<p>'.$t('Keine passenden Inhalte.').'</p>';$h.='<p role="status">'.$t('Seite {page} von {pages} · {count} Inhalte',['page'=>$page['page'],'pages'=>$page['pages'],'count'=>$page['total']]).'</p><nav class="editorial-library-pages">';foreach([-1=>'Vorherige Seite',1=>'Nächste Seite']as$delta=>$label){$number=$page['page']+$delta;if($number<1||$number>$page['pages'])continue;$h.='<a class="btn btn-outline theme-secondary" data-nav href="'.Html::e($url(['hub_query'=>$page['query'],'hub_type'=>$page['type'],'hub_page'=>$number])).'">'.$t($label).'</a>';}return$h.'</nav></section>';
    }
}
